(window.ABDI_PAKET = window.ABDI_PAKET || {})["skd.tkp.pelayanan-publik.1"] = [{"i":2674,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Menjelang jam tutup layanan, seorang warga lanjut usia datang untuk mengurus dokumen, tetapi satu syaratnya kurang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melayaninya dengan sabar, menjelaskan syarat yang kurang, dan mencatat berkasnya agar besok bisa langsung diproses.” Tetap ramah dan memberi jalan keluar yang jelas.\nPilihan terendah (nilai 1): “Menolak melayani karena syaratnya tidak lengkap dan waktu sudah habis.” Mengabaikan warga yang membutuhkan; bertentangan dengan pelayanan prima.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memberikan lembar daftar syarat lalu mempersilakannya pulang.","Melayaninya dengan sabar, menjelaskan syarat yang kurang, dan mencatat berkasnya agar besok bisa langsung diproses.","Memintanya bertanya ke petugas lain karena jam layanan hampir habis.","Menjelaskan syarat yang kurang dan memintanya kembali besok pagi.","Menolak melayani karena syaratnya tidak lengkap dan waktu sudah habis."],"s":[3,5,2,4,1],"w":["Informasi diberikan, tetapi tanpa penjelasan atau bantuan.","Tetap ramah dan memberi jalan keluar yang jelas.","Melempar tanggung jawab kepada rekan.","Sudah benar, tetapi belum memudahkan kedatangan berikutnya.","Mengabaikan warga yang membutuhkan; bertentangan dengan pelayanan prima."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":2675,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Antrean di loket Anda panjang, dan seorang warga marah karena merasa terlalu lama menunggu. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendengarkan keluhannya dengan tenang, meminta maaf atas waktu tunggu, dan menjelaskan perkiraan gilirannya.” Meredakan dengan empati dan memberi informasi yang jelas.\nPilihan terendah (nilai 1): “Membalas dengan nada tinggi agar warga itu tidak semena-mena.” Memperkeruh suasana dan tidak profesional.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Meminta petugas keamanan menenangkan warga tersebut.","Meminta maaf dan memintanya menunggu sesuai nomor antrean.","Membalas dengan nada tinggi agar warga itu tidak semena-mena.","Tetap melayani antrean seperti biasa tanpa menanggapi kemarahannya.","Mendengarkan keluhannya dengan tenang, meminta maaf atas waktu tunggu, dan menjelaskan perkiraan gilirannya."],"s":[2,4,1,3,5],"w":["Mengalihkan masalah yang sebenarnya bisa diselesaikan dengan komunikasi.","Sopan, tetapi belum menjawab kekhawatirannya.","Memperkeruh suasana dan tidak profesional.","Layanan berjalan, tetapi keluhan diabaikan.","Meredakan dengan empati dan memberi informasi yang jelas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":2676,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga meminta pengurusan izinnya dipercepat dengan menawarkan uang terima kasih. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan sopan, menjelaskan bahwa layanan tidak memungut biaya tambahan, lalu memproses sesuai antrean.” Menjaga integritas sekaligus memberi pemahaman kepada warga.\nPilihan terendah (nilai 1): “Menerima uang itu karena tidak ada yang mengetahuinya.” Menerima gratifikasi melanggar hukum dan kode etik ASN.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menolak pemberian itu dan memproses izinnya sesuai prosedur.","Menolak dengan sopan, menjelaskan bahwa layanan tidak memungut biaya tambahan, lalu memproses sesuai antrean.","Menerima uang itu karena tidak ada yang mengetahuinya.","Menolak tanpa menjelaskan alasannya.","Mengatakan akan memikirkannya terlebih dahulu."],"s":[4,5,1,3,2],"w":["Tegas dan sesuai prosedur, hanya kurang penjelasan.","Menjaga integritas sekaligus memberi pemahaman kepada warga.","Menerima gratifikasi melanggar hukum dan kode etik ASN.","Benar menolak, tetapi warga tidak paham alasannya.","Ragu-ragu membuka peluang gratifikasi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":2677,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga penyandang disabilitas kesulitan mengisi formulir di kantor Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendampinginya mengisi formulir dan mengusulkan agar kantor menyediakan formulir yang lebih mudah diakses.” Membantu langsung sekaligus memperbaiki layanan.\nPilihan terendah (nilai 1): “Membiarkannya karena mengisi formulir adalah tanggung jawab pemohon.” Abai terhadap warga yang membutuhkan layanan khusus.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mendampinginya mengisi formulir dan mengusulkan agar kantor menyediakan formulir yang lebih mudah diakses.","Membantunya mengisi formulir sampai selesai.","Menjelaskan cara mengisi formulir dari meja Anda.","Menyarankannya datang lagi bersama keluarga yang bisa membantu.","Membiarkannya karena mengisi formulir adalah tanggung jawab pemohon."],"s":[5,4,3,2,1],"w":["Membantu langsung sekaligus memperbaiki layanan.","Membantu dengan baik, tetapi belum memikirkan perbaikan layanan.","Ada bantuan, tetapi kurang sesuai kebutuhannya.","Menunda layanan dan membebani warga.","Abai terhadap warga yang membutuhkan layanan khusus."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":2678,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Anda melihat informasi syarat layanan di papan pengumuman kantor sudah tidak sesuai dengan aturan terbaru. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melapor ke atasan dan mengusulkan pembaruan, sambil menjelaskan syarat yang benar kepada warga yang datang.” Memperbaiki sumber masalah dan mencegah warga dirugikan saat ini juga.\nPilihan terendah (nilai 1): “Membiarkannya karena mengurus papan pengumuman bukan tugas Anda.” Tidak peduli pada mutu layanan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjelaskan syarat terbaru hanya kepada warga yang bertanya.","Melapor ke atasan dan mengusulkan pembaruan, sambil menjelaskan syarat yang benar kepada warga yang datang.","Menunggu ada keluhan warga sebelum melaporkannya.","Melaporkannya kepada atasan agar segera diperbarui.","Membiarkannya karena mengurus papan pengumuman bukan tugas Anda."],"s":[3,5,2,4,1],"w":["Hanya membantu sebagian warga.","Memperbaiki sumber masalah dan mencegah warga dirugikan saat ini juga.","Menunggu masalah muncul dulu.","Tepat, tetapi warga yang datang hari ini masih bisa salah paham.","Tidak peduli pada mutu layanan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":2679,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Sistem antrean daring kantor Anda sedang gangguan, sementara banyak warga sudah datang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Segera menjalankan antrean manual yang tertib, mengumumkannya kepada warga, dan melaporkan gangguan ke bagian TI.” Layanan tetap berjalan dan gangguan ditangani.\nPilihan terendah (nilai 1): “Menutup layanan hari itu tanpa pemberitahuan.” Merugikan warga dan tidak transparan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menyarankan warga datang lagi besok.","Melaporkan gangguan ke bagian TI dan meminta warga menunggu perbaikan.","Menutup layanan hari itu tanpa pemberitahuan.","Segera menjalankan antrean manual yang tertib, mengumumkannya kepada warga, dan melaporkan gangguan ke bagian TI.","Meminta warga menunggu sampai sistem pulih tanpa kepastian waktu."],"s":[2,4,1,5,3],"w":["Membebani warga.","Gangguan dilaporkan, tetapi warga tetap tertahan.","Merugikan warga dan tidak transparan.","Layanan tetap berjalan dan gangguan ditangani.","Pasif dan membuat warga menunggu tanpa kepastian."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":2680,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang kerabat Anda meminta didahulukan dalam antrean layanan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan dengan sopan bahwa semua warga dilayani sesuai antrean, lalu membantunya mengambil nomor antrean.” Adil dan tetap ramah kepada kerabat.\nPilihan terendah (nilai 1): “Langsung mendahulukannya karena ia keluarga sendiri.” Nepotisme dan tidak adil bagi warga lain.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memintanya mengambil nomor antrean dan menunggu giliran.","Langsung mendahulukannya karena ia keluarga sendiri.","Mendahulukannya hanya jika antrean sedang tidak terlalu panjang.","Menyarankannya datang lebih pagi lain kali.","Menjelaskan dengan sopan bahwa semua warga dilayani sesuai antrean, lalu membantunya mengambil nomor antrean."],"s":[4,1,2,3,5],"w":["Adil, tetapi kurang komunikatif.","Nepotisme dan tidak adil bagi warga lain.","Masih membuka peluang perlakuan khusus.","Tidak menjawab permintaannya dengan jelas.","Adil dan tetap ramah kepada kerabat."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":2681,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga mengeluhkan pelayanan yang kurang ramah dari rekan kerja Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Meminta maaf kepada warga, membantu menyelesaikan urusannya, lalu menyampaikan masukan itu kepada rekan secara baik-baik.” Memulihkan kepercayaan warga dan membantu rekan memperbaiki diri.\nPilihan terendah (nilai 1): “Membela rekan Anda dan menyalahkan warga.” Menyalahkan warga merusak kepercayaan publik.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Meminta maaf kepada warga, membantu menyelesaikan urusannya, lalu menyampaikan masukan itu kepada rekan secara baik-baik.","Membela rekan Anda dan menyalahkan warga.","Menyarankan warga menyampaikan keluhannya langsung kepada rekan tersebut.","Meminta maaf dan membantu menyelesaikan urusan warga tersebut.","Mencatat keluhan dan meneruskannya ke atasan."],"s":[5,1,2,4,3],"w":["Memulihkan kepercayaan warga dan membantu rekan memperbaiki diri.","Menyalahkan warga merusak kepercayaan publik.","Melempar masalah kepada warga.","Urusan warga selesai, tetapi akar masalahnya dibiarkan.","Sesuai prosedur, tetapi warga belum terbantu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":2682,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Anda ditugaskan melayani warga di daerah terpencil pada akhir pekan dalam program layanan keliling. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyiapkan perlengkapan dan informasi layanan sebaik mungkin, lalu berangkat sesuai jadwal.” Siap melayani dengan persiapan matang.\nPilihan terendah (nilai 1): “Menolak karena akhir pekan adalah waktu pribadi.” Menolak tugas pelayanan tanpa alasan yang sah.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menolak karena akhir pekan adalah waktu pribadi.","Menerima tugas itu dan berangkat sesuai jadwal.","Menyiapkan perlengkapan dan informasi layanan sebaik mungkin, lalu berangkat sesuai jadwal.","Menerima tugas, tetapi meminta jadwalnya digeser jika memungkinkan.","Meminta rekan lain menggantikan Anda."],"s":[1,4,5,3,2],"w":["Menolak tugas pelayanan tanpa alasan yang sah.","Bertanggung jawab, tetapi tanpa persiapan khusus.","Siap melayani dengan persiapan matang.","Bersedia dengan syarat; kurang mengutamakan kebutuhan warga.","Menghindari tugas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3106,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga menyerahkan formulir yang sebagian datanya keliru, padahal antrean di belakangnya masih panjang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menunjukkan bagian yang keliru, membantunya membetulkan di tempat, lalu memproses berkasnya.” Masalah selesai tanpa membuat warga kembali lagi.\nPilihan terendah (nilai 1): “Membetulkan sendiri data di formulir tanpa bertanya kepada warga, karena antrean di belakangnya panjang dan kesalahannya tampak sepele.” Mengubah data warga tanpa persetujuannya.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengembalikan formulir dan memintanya mengisi ulang.","Memintanya datang lagi besok karena antrean sedang panjang.","Menunjukkan bagian yang keliru, membantunya membetulkan di tempat, lalu memproses berkasnya.","Membetulkan sendiri data di formulir tanpa bertanya kepada warga, karena antrean di belakangnya panjang dan kesalahannya tampak sepele.","Menandai bagian yang salah dan memintanya membetulkan di meja samping, lalu mengantre lagi."],"s":[3,2,5,1,4],"w":["Prosedural, tanpa bantuan.","Menunda layanan yang bisa selesai hari itu.","Masalah selesai tanpa membuat warga kembali lagi.","Mengubah data warga tanpa persetujuannya.","Benar, tetapi warga harus mengantre dua kali."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3107,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang ibu hamil tua berdiri di antrean umum yang panjang, sementara loket prioritas sedang kosong. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengarahkannya ke loket prioritas dan melayaninya sesuai ketentuan.” Memberikan hak layanan prioritas yang memang miliknya.\nPilihan terendah (nilai 1): “Memintanya tetap mengantre supaya warga lain tidak protes.” Mengabaikan hak kelompok rentan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengarahkannya ke loket prioritas dan melayaninya sesuai ketentuan.","Memintanya tetap mengantre supaya warga lain tidak protes.","Menawarinya kursi sambil menunggu giliran di antrean umum, lalu memastikan ia tidak terlalu lama berdiri.","Membiarkannya karena ia tidak meminta prioritas.","Menyarankannya datang lagi saat antrean sepi."],"s":[5,1,4,3,2],"w":["Memberikan hak layanan prioritas yang memang miliknya.","Mengabaikan hak kelompok rentan.","Peduli, tetapi hak prioritasnya belum diberikan.","Pasif.","Menunda layanan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3108,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga lanjut usia tidak bisa membaca dan menulis, padahal ia harus mengisi formulir permohonan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membacakan formulir, menuliskan jawabannya, lalu membacakan ulang sebelum ia membubuhkan cap jempol.” Membantu tanpa mengorbankan ketelitian.\nPilihan terendah (nilai 1): “Mengisi formulir dengan data perkiraan supaya cepat selesai.” Data tidak akurat dan merugikan warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menyarankannya meminta bantuan pengunjung lain yang sedang menunggu, karena petugas harus tetap melayani antrean.","Membacakan formulir, menuliskan jawabannya, lalu membacakan ulang sebelum ia membubuhkan cap jempol.","Membantu mengisikan formulirnya sesuai keterangannya.","Memintanya datang lagi bersama keluarga yang bisa menulis.","Mengisi formulir dengan data perkiraan supaya cepat selesai."],"s":[3,5,4,2,1],"w":["Melempar bantuan kepada orang lain.","Membantu tanpa mengorbankan ketelitian.","Membantu, tetapi isinya tidak dipastikan ulang.","Menunda dan membebani warga.","Data tidak akurat dan merugikan warga."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3109,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga negara asing datang ke loket dan kesulitan memahami prosedur yang hanya tertulis dalam bahasa Indonesia. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan prosedur dengan bahasa sederhana atau bahasa Inggris semampunya, memberi contoh berkas, dan mengusulkan panduan dwibahasa.” Melayani sekaligus memperbaiki informasi layanan.\nPilihan terendah (nilai 1): “Menolak melayaninya dan memintanya memakai jasa agen yang bisa berbahasa asing, karena prosedur kantor hanya tersedia dalam bahasa Indonesia.” Diskriminatif dan mendorong ke jalur tidak resmi.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memintanya kembali bersama penerjemah.","Menjelaskan prosedurnya pelan-pelan dengan bahasa sederhana.","Menolak melayaninya dan memintanya memakai jasa agen yang bisa berbahasa asing, karena prosedur kantor hanya tersedia dalam bahasa Indonesia.","Menjelaskan prosedur dengan bahasa sederhana atau bahasa Inggris semampunya, memberi contoh berkas, dan mengusulkan panduan dwibahasa.","Memberikan brosur berbahasa Indonesia dan mempersilakannya membaca."],"s":[2,4,1,5,3],"w":["Menunda layanan.","Membantu, tanpa perbaikan untuk ke depan.","Diskriminatif dan mendorong ke jalur tidak resmi.","Melayani sekaligus memperbaiki informasi layanan.","Informasi diberikan, tetapi tidak dipahami."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3110,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga meminta salinan dokumen kependudukan milik tetangganya dengan alasan disuruh, tanpa membawa surat kuasa. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan sopan, menjelaskan bahwa data pribadi hanya diberikan kepada pemiliknya atau kuasanya, dan memberi tahu syarat surat kuasa.” Melindungi data pribadi sambil memberi jalan yang sah.\nPilihan terendah (nilai 1): “Memberikannya karena warga itu mengenal pemilik dokumen.” Membocorkan data pribadi.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memintanya menunggu sampai pemilik dokumen bisa dihubungi.","Menolak permintaan itu karena tidak ada surat kuasa.","Menolak dengan sopan, menjelaskan bahwa data pribadi hanya diberikan kepada pemiliknya atau kuasanya, dan memberi tahu syarat surat kuasa.","Menanyakan kepada atasan apakah salinan itu boleh diberikan, karena warga tersebut mengaku sudah mendapat izin lisan dari pemiliknya dan tampak terburu-buru.","Memberikannya karena warga itu mengenal pemilik dokumen."],"s":[2,4,5,3,1],"w":["Tidak tegas dan membuang waktu.","Tepat, tetapi tanpa jalan keluar.","Melindungi data pribadi sambil memberi jalan yang sah.","Ragu pada aturan yang sudah jelas.","Membocorkan data pribadi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3111,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Petugas loket sebelah mendadak sakit, sehingga antrean di loket Anda menjadi dua kali lebih panjang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengumumkan perubahan kepada warga, melayani dengan cepat tanpa mengurangi ketelitian, dan meminta atasan menugaskan petugas pengganti.” Layanan tetap berjalan dan solusi dicari.\nPilihan terendah (nilai 1): “Mempercepat layanan dengan melewatkan pemeriksaan kelengkapan berkas, karena warga lebih senang cepat selesai dan kesalahannya bisa diperbaiki belakangan.” Mengorbankan ketelitian dan aturan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Melayani seperti biasa dan membiarkan antrean berjalan apa adanya.","Meminta sebagian warga pulang dan datang esok hari.","Mempercepat layanan dengan melewatkan pemeriksaan kelengkapan berkas, karena warga lebih senang cepat selesai dan kesalahannya bisa diperbaiki belakangan.","Mengumumkan perubahan kepada warga, melayani dengan cepat tanpa mengurangi ketelitian, dan meminta atasan menugaskan petugas pengganti.","Melayani lebih cepat dari biasanya tanpa memberi tahu warga."],"s":[3,2,1,5,4],"w":["Pasif.","Membebani warga.","Mengorbankan ketelitian dan aturan.","Layanan tetap berjalan dan solusi dicari.","Bekerja keras, tetapi warga tidak mendapat informasi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3112,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga merekam Anda dengan ponselnya saat Anda sedang melayaninya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tetap melayani dengan ramah dan sesuai prosedur, karena layanan publik memang terbuka untuk diawasi.” Profesional dan transparan.\nPilihan terendah (nilai 1): “Merebut ponselnya dan menghapus rekamannya.” Melanggar hak warga dan memperkeruh suasana.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Membiarkannya dan melayani seadanya.","Meminta rekan lain menggantikan Anda melayani warga itu.","Merebut ponselnya dan menghapus rekamannya.","Tetap melayani, tetapi berhenti sejenak untuk menanyakan dengan sopan tujuan perekaman dan meminta rekamannya tidak disebarkan.","Tetap melayani dengan ramah dan sesuai prosedur, karena layanan publik memang terbuka untuk diawasi."],"s":[3,2,1,4,5],"w":["Pasif.","Menghindar.","Melanggar hak warga dan memperkeruh suasana.","Wajar, tetapi terkesan defensif.","Profesional dan transparan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3113,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga marah di kolom komentar media sosial instansi karena izinnya belum terbit melewati waktu yang dijanjikan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membalas dengan sopan, meminta data permohonannya lewat pesan, mengecek penyebab keterlambatan, lalu memberi kepastian waktu.” Menanggapi secara terbuka dan menyelesaikan masalahnya.\nPilihan terendah (nilai 1): “Menghapus komentarnya dan memblokir akunnya.” Menutupi keluhan publik.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Membalas dengan sopan, meminta data permohonannya lewat pesan, mengecek penyebab keterlambatan, lalu memberi kepastian waktu.","Menghapus komentarnya dan memblokir akunnya.","Menyerahkan urusan komentar itu kepada admin media sosial.","Membiarkan komentar itu karena nanti tenggelam sendiri.","Membalas dengan permintaan maaf, menjelaskan bahwa permohonan sedang menumpuk karena banyak warga mengajukan izin bulan ini, dan menyarankannya datang ke kantor."],"s":[5,1,3,2,4],"w":["Menanggapi secara terbuka dan menyelesaikan masalahnya.","Menutupi keluhan publik.","Melempar ke pihak lain.","Mengabaikan keluhan.","Sopan, tetapi penyebab keterlambatannya belum dicek."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3114,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga menelepon kantor setelah jam kerja untuk menanyakan status permohonannya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjawab singkat, mencatat nomor permohonannya, lalu mengabarkan statusnya keesokan pagi.” Responsif sambil tetap tertib waktu.\nPilihan terendah (nilai 1): “Memarahinya karena menelepon di luar jam kerja.” Tidak sopan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjawab singkat, mencatat nomor permohonannya, lalu mengabarkan statusnya keesokan pagi.","Membiarkan telepon itu karena sudah di luar jam kerja.","Menjawab bahwa semua petugas sudah pulang dan memintanya menelepon lagi pada jam kerja, tanpa mencatat keperluannya.","Memberi tahu jam layanan dan memintanya menelepon lagi besok pagi.","Memarahinya karena menelepon di luar jam kerja."],"s":[5,3,2,4,1],"w":["Responsif sambil tetap tertib waktu.","Pasif.","Menghindar.","Benar, tetapi warga belum terbantu.","Tidak sopan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3115,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga datang mengurus dokumen tanpa membawa KTP asli, hanya fotokopinya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memverifikasi datanya di sistem bila aturan membolehkan; bila tidak, menjelaskan syaratnya dan menyimpan berkasnya supaya besok langsung diproses.” Mencari jalan yang sah dan memudahkan.\nPilihan terendah (nilai 1): “Memproses berkasnya tanpa verifikasi karena wajahnya sudah dikenal petugas dan data di fotokopi KTP tampak sama dengan data yang tersimpan di sistem.” Melanggar prosedur verifikasi.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjelaskan bahwa KTP asli wajib dibawa dan memintanya kembali besok.","Memproses berkasnya tanpa verifikasi karena wajahnya sudah dikenal petugas dan data di fotokopi KTP tampak sama dengan data yang tersimpan di sistem.","Memintanya mengambil nomor antrean baru setelah membawa KTP asli.","Memverifikasi datanya di sistem bila aturan membolehkan; bila tidak, menjelaskan syaratnya dan menyimpan berkasnya supaya besok langsung diproses.","Menyuruhnya pulang tanpa penjelasan."],"s":[4,1,3,5,2],"w":["Benar, tetapi kurang solutif.","Melanggar prosedur verifikasi.","Prosedural.","Mencari jalan yang sah dan memudahkan.","Tidak informatif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3116,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Anda menyadari dokumen seorang warga tercetak dengan nama yang salah karena Anda keliru mengetik. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengakui kesalahan, meminta maaf, mencetak ulang dokumen yang benar saat itu juga, dan menarik dokumen yang salah.” Bertanggung jawab dan tuntas.\nPilihan terendah (nilai 1): “Membiarkannya karena warga belum menyadari kesalahan itu.” Tidak jujur dan merugikan warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mencetak ulang dokumen dan memintanya menunggu sebentar.","Mengakui kesalahan, meminta maaf, mencetak ulang dokumen yang benar saat itu juga, dan menarik dokumen yang salah.","Memintanya mengajukan permohonan perbaikan dari awal.","Membiarkannya karena warga belum menyadari kesalahan itu.","Melaporkan kesalahan itu kepada atasan, mencatatnya di buku kejadian, dan menunggu arahan sebelum mencetak ulang dokumen."],"s":[4,5,2,1,3],"w":["Diperbaiki, tetapi tanpa pengakuan kesalahan.","Bertanggung jawab dan tuntas.","Membebani warga atas kesalahan petugas.","Tidak jujur dan merugikan warga.","Menunggu, padahal bisa segera diperbaiki."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3117,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Hasil survei kepuasan menunjukkan banyak warga mengeluhkan lamanya waktu tunggu di unit Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mencari tahap layanan yang paling lambat, mengusulkan perbaikan alurnya, dan memantau hasilnya.” Survei dijadikan bahan perbaikan nyata.\nPilihan terendah (nilai 1): “Mengubah hasil survei supaya unit terlihat baik.” Memanipulasi data.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengusulkan agar hasil survei dibahas dalam rapat unit dan mengajak rekan menyampaikan pendapat tentang penyebabnya.","Menganggap keluhan itu wajar karena pengunjung memang banyak.","Mengubah hasil survei supaya unit terlihat baik.","Menunggu atasan menanggapi hasil survei.","Mencari tahap layanan yang paling lambat, mengusulkan perbaikan alurnya, dan memantau hasilnya."],"s":[4,2,1,3,5],"w":["Langkah awal yang baik, belum ada tindakan.","Membela diri.","Memanipulasi data.","Pasif.","Survei dijadikan bahan perbaikan nyata."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3118,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Setelah urusannya selesai, seorang warga memberikan sekotak kue sebagai ucapan terima kasih kepada Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan halus sambil menjelaskan bahwa layanan tidak boleh disertai pemberian, dan berterima kasih atas niat baiknya.” Menjaga integritas dengan sopan.\nPilihan terendah (nilai 1): “Menerimanya dan berjanji urusan berikutnya akan dibantu lebih cepat.” Gratifikasi dan perlakuan istimewa.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menerimanya dan berjanji urusan berikutnya akan dibantu lebih cepat.","Menolak pemberian itu dengan sopan.","Menolak dengan halus sambil menjelaskan bahwa layanan tidak boleh disertai pemberian, dan berterima kasih atas niat baiknya.","Menerimanya, lalu melaporkannya kepada unit pengendali gratifikasi.","Menerimanya karena tidak enak menolak niat baik warga, apalagi pemberiannya hanya makanan dan diberikan setelah layanan selesai."],"s":[1,4,5,3,2],"w":["Gratifikasi dan perlakuan istimewa.","Tepat, tanpa penjelasan.","Menjaga integritas dengan sopan.","Sesuai prosedur, tetapi sebaiknya ditolak sejak awal.","Tidak tegas pada integritas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3119,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang calo menawarkan kerja sama: ia membawa berkas warga kepada Anda dan membagi imbalannya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak tegas, mencatat identitasnya, dan melaporkannya kepada atasan serta pengelola pengaduan.” Memutus praktik percaloan.\nPilihan terendah (nilai 1): “Menerima tawaran itu karena berkas warga tetap diperiksa sesuai syarat dan negara tidak dirugikan sedikit pun.” Korupsi dan merugikan warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menolak tegas, mencatat identitasnya, dan melaporkannya kepada atasan serta pengelola pengaduan.","Menerima tawaran itu karena berkas warga tetap diperiksa sesuai syarat dan negara tidak dirugikan sedikit pun.","Menolak tawaran itu dengan tegas.","Pura-pura tidak mendengar tawarannya.","Menolak dan memintanya tidak datang lagi."],"s":[5,1,4,2,3],"w":["Memutus praktik percaloan.","Korupsi dan merugikan warga.","Benar, tanpa tindak lanjut.","Menghindar.","Praktiknya tidak ditindaklanjuti."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3120,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga meminta nomor ponsel pribadi Anda supaya mudah menanyakan kelanjutan berkasnya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memberikan nomor layanan resmi dan nomor pengaduan kantor, serta menjelaskan cara memantau berkas.” Menjaga batas pribadi tanpa mengurangi layanan.\nPilihan terendah (nilai 1): “Memberikan nomor pribadi dan menawarkan \"jalur khusus\" di luar kantor.” Membuka peluang pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memberikan nomor telepon kantor.","Menyarankannya datang langsung ke kantor bila ingin bertanya.","Mengaku tidak punya ponsel.","Memberikan nomor layanan resmi dan nomor pengaduan kantor, serta menjelaskan cara memantau berkas.","Memberikan nomor pribadi dan menawarkan \"jalur khusus\" di luar kantor."],"s":[4,3,2,5,1],"w":["Sopan, informasinya kurang lengkap.","Kurang memudahkan.","Tidak jujur.","Menjaga batas pribadi tanpa mengurangi layanan.","Membuka peluang pungli."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3121,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang pejabat daerah meminta urusan pribadinya didahulukan tanpa mengantre. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan dengan hormat bahwa semua warga dilayani sesuai antrean, lalu membantunya mengambil nomor dan menyiapkan berkas.” Adil tanpa mengurangi rasa hormat.\nPilihan terendah (nilai 1): “Langsung mendahulukannya karena jabatannya.” Diskriminatif terhadap warga lain.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjelaskan dengan hormat bahwa semua warga dilayani sesuai antrean, lalu membantunya mengambil nomor dan menyiapkan berkas.","Langsung mendahulukannya karena jabatannya.","Menghindari pejabat itu dengan meminta rekan lain yang melayaninya.","Menyerahkan keputusan kepada atasan.","Memintanya mengambil nomor antrean seperti warga lain."],"s":[5,1,2,3,4],"w":["Adil tanpa mengurangi rasa hormat.","Diskriminatif terhadap warga lain.","Menghindar.","Melempar keputusan yang sudah jelas.","Adil, kurang luwes."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3122,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga lanjut usia tampak tersesat di gedung kantor dan tidak tahu loket yang dituju. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menghampirinya, menanyakan keperluannya, lalu mengantarnya ke loket yang tepat.” Proaktif dan ramah.\nPilihan terendah (nilai 1): “Mengabaikannya karena bukan tugas Anda.” Abai.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menghampirinya, menanyakan keperluannya, lalu mengantarnya ke loket yang tepat.","Menunggu ia bertanya lebih dulu.","Menunjukkan arah loket yang ia cari dengan jelas.","Mengabaikannya karena bukan tugas Anda.","Memintanya bertanya kepada petugas keamanan di pintu masuk, karena mereka lebih hafal letak setiap loket."],"s":[5,3,4,1,2],"w":["Proaktif dan ramah.","Pasif.","Membantu, kurang tuntas untuk warga lansia.","Abai.","Melempar tanggung jawab."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3123,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Banyak warga lanjut usia kesulitan memakai mesin pendaftaran mandiri yang baru dipasang di kantor. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendampingi mereka memakai mesin, lalu mengusulkan petugas pendamping dan petunjuk bergambar di dekat mesin.” Membantu sekaligus memperbaiki sistem.\nPilihan terendah (nilai 1): “Membiarkan mereka mencoba sendiri supaya terbiasa dengan teknologi.” Abai pada kebutuhan warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mendampingi mereka memakai mesin, lalu mengusulkan petugas pendamping dan petunjuk bergambar di dekat mesin.","Membantu setiap warga lansia yang terlihat kesulitan.","Menyarankan mereka datang bersama anak atau cucu.","Menempelkan petunjuk tertulis di mesin.","Membiarkan mereka mencoba sendiri supaya terbiasa dengan teknologi."],"s":[5,4,2,3,1],"w":["Membantu sekaligus memperbaiki sistem.","Membantu, tanpa perbaikan.","Membebani warga.","Kurang cocok untuk warga lansia.","Abai pada kebutuhan warga."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3124,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga mengancam akan melaporkan Anda kepada atasan karena permohonannya ditolak, padahal penolakan itu sesuai aturan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tetap tenang, menjelaskan dasar aturan dan syarat yang perlu dipenuhi, serta mempersilakannya memakai jalur pengaduan bila keberatan.” Tegas pada aturan dan terbuka pada pengawasan.\nPilihan terendah (nilai 1): “Mengabulkan permohonannya supaya tidak dilaporkan, toh kekurangannya hanya satu syarat administrasi dan warga itu sudah datang berkali-kali ke kantor.” Melanggar aturan karena takut.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengabulkan permohonannya supaya tidak dilaporkan, toh kekurangannya hanya satu syarat administrasi dan warga itu sudah datang berkali-kali ke kantor.","Menjelaskan alasan penolakan dengan sopan.","Mengulur waktu sampai warga itu pergi sendiri.","Tetap tenang, menjelaskan dasar aturan dan syarat yang perlu dipenuhi, serta mempersilakannya memakai jalur pengaduan bila keberatan.","Memanggil atasan supaya atasan yang menjelaskan."],"s":[1,4,2,5,3],"w":["Melanggar aturan karena takut.","Benar, belum memberi jalan keluar.","Menghindar.","Tegas pada aturan dan terbuka pada pengawasan.","Melempar penjelasan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3125,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Anda harus menyampaikan kepada seorang warga bahwa permohonannya tidak dapat diproses karena belum memenuhi syarat. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menunjukkan syarat yang belum terpenuhi dan cara melengkapinya.” Jujur dan memberi solusi.\nPilihan terendah (nilai 1): “Mengatakan berkasnya hilang supaya tidak perlu menjelaskan.” Berbohong.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengembalikan berkas dengan catatan singkat.","Mengatakan berkasnya masih diproses supaya warga tidak kecewa.","Mengatakan berkasnya hilang supaya tidak perlu menjelaskan.","Menyampaikan bahwa syaratnya belum lengkap dan memberinya daftar syarat, lalu mempersilakannya bertanya bila ada yang belum jelas.","Menunjukkan syarat yang belum terpenuhi dan cara melengkapinya."],"s":[3,2,1,4,5],"w":["Minim penjelasan.","Menunda kabar dan memberi harapan palsu.","Berbohong.","Informatif, tetapi tidak menunjukkan bagian yang kurang.","Jujur dan memberi solusi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3126,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Banyak warga salah masuk loket karena papan petunjuk arah di kantor kurang jelas. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengarahkan warga yang salah loket, lalu mengusulkan papan petunjuk yang lebih jelas kepada atasan.” Membantu sekaligus memperbaiki sumber masalah.\nPilihan terendah (nilai 1): “Tetap memproses urusan yang bukan kewenangan loket Anda supaya warga tidak perlu pindah dan mengantre lagi dari awal.” Melanggar prosedur.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Tetap memproses urusan yang bukan kewenangan loket Anda supaya warga tidak perlu pindah dan mengantre lagi dari awal.","Meminta warga membaca papan petunjuk dengan lebih teliti.","Menyuruh warga mengantre ulang di loket lain tanpa penjelasan.","Mengarahkan warga yang salah loket, lalu mengusulkan papan petunjuk yang lebih jelas kepada atasan.","Mengarahkan setiap warga yang salah loket ke loket yang benar."],"s":[1,3,2,5,4],"w":["Melanggar prosedur.","Menyalahkan warga.","Tidak membantu.","Membantu sekaligus memperbaiki sumber masalah.","Membantu, sumber masalah dibiarkan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3127,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Kotak saran di kantor Anda penuh, tetapi tidak ada yang membukanya selama berbulan-bulan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengusulkan jadwal rutin membuka kotak saran, merekap isinya, dan menindaklanjuti masukan yang relevan.” Masukan warga menjadi berguna.\nPilihan terendah (nilai 1): “Membuang isi kotak saran supaya terlihat rapi.” Mengabaikan suara warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Membuka kotak saran dan menyerahkan isinya kepada atasan.","Membuang isi kotak saran supaya terlihat rapi.","Mengusulkan jadwal rutin membuka kotak saran, merekap isinya, dan menindaklanjuti masukan yang relevan.","Menunggu atasan menugaskan seseorang untuk membukanya, karena kotak saran menjadi tanggung jawab bagian umum dan kuncinya dipegang mereka.","Membiarkannya karena bukan tugas Anda."],"s":[4,1,5,3,2],"w":["Langkah baik, belum ada tindak lanjut.","Mengabaikan suara warga.","Masukan warga menjadi berguna.","Pasif.","Tidak peduli."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3128,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga meminta informasi tentang penggunaan anggaran kegiatan di kantor Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan bahwa informasi itu dapat dimohonkan sebagai informasi publik, membantunya mengajukan permohonan ke pejabat pengelola informasi, dan memastikan ia mendapat jawaban.” Mendukung keterbukaan informasi.\nPilihan terendah (nilai 1): “Mengatakan informasi itu rahasia negara supaya ia tidak bertanya lagi.” Berbohong dan menghambat hak warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjelaskan bahwa informasi itu dapat dimohonkan sebagai informasi publik, membantunya mengajukan permohonan ke pejabat pengelola informasi, dan memastikan ia mendapat jawaban.","Memintanya menunggu sampai laporan keuangan tahun ini selesai.","Mengatakan informasi itu rahasia negara supaya ia tidak bertanya lagi.","Memintanya mengajukan surat resmi tanpa menjelaskan caranya.","Mengarahkannya ke pejabat pengelola informasi."],"s":[5,2,1,3,4],"w":["Mendukung keterbukaan informasi.","Menunda tanpa dasar.","Berbohong dan menghambat hak warga.","Prosedural, minim bantuan.","Tepat, kurang pendampingan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3129,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang anak SMP datang sendirian untuk mengurus dokumen orang tuanya yang sedang sakit. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menanyakan keperluannya, menjelaskan syarat surat kuasa atau layanan jemput bola bagi warga yang sakit, dan mencatat kontak keluarganya.” Membantu sesuai aturan dan mempertimbangkan keadaan.\nPilihan terendah (nilai 1): “Memproses dokumen itu tanpa syarat apa pun karena kasihan.” Melanggar prosedur.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjelaskan syarat pengurusan dan menuliskannya untuk orang tuanya.","Menanyakan keperluannya, menjelaskan syarat surat kuasa atau layanan jemput bola bagi warga yang sakit, dan mencatat kontak keluarganya.","Memintanya datang bersama orang dewasa.","Memintanya pulang karena anak-anak tidak boleh mengurus dokumen.","Memproses dokumen itu tanpa syarat apa pun karena kasihan."],"s":[4,5,3,2,1],"w":["Membantu, belum mencari alternatif.","Membantu sesuai aturan dan mempertimbangkan keadaan.","Prosedural tanpa solusi.","Menolak tanpa penjelasan.","Melanggar prosedur."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3130,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Listrik padam saat jam layanan, sementara antrean warga masih panjang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan keadaan kepada warga, mengerjakan layanan yang bisa dilakukan manual, dan mencatat warga yang harus menunggu agar didahulukan saat listrik menyala.” Layanan tetap berjalan dan adil.\nPilihan terendah (nilai 1): “Pulang lebih awal karena tidak bisa bekerja.” Meninggalkan tugas.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menunggu listrik menyala tanpa memberi informasi.","Meminta semua warga kembali besok.","Menjelaskan keadaan kepada warga, mengerjakan layanan yang bisa dilakukan manual, dan mencatat warga yang harus menunggu agar didahulukan saat listrik menyala.","Meminta warga menunggu dan memberi kabar perkiraan waktu listrik menyala.","Pulang lebih awal karena tidak bisa bekerja."],"s":[3,2,5,4,1],"w":["Pasif.","Membebani warga.","Layanan tetap berjalan dan adil.","Informatif, tetapi layanan terhenti.","Meninggalkan tugas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3131,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Warga sering mengeluhkan ruang tunggu kantor yang panas dan sempit. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengusulkan perbaikan ruang tunggu dan, sambil menunggu, mengatur jadwal kedatangan supaya ruang tidak penuh.” Ada solusi jangka pendek dan panjang.\nPilihan terendah (nilai 1): “Meminta warga menunggu di luar gedung tanpa naungan.” Merugikan warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengusulkan perbaikan ruang tunggu kepada atasan.","Meminta warga menunggu di luar gedung tanpa naungan.","Menganggapnya wajar karena kantornya memang kecil.","Meminta maaf kepada warga yang mengeluh dan menjelaskan bahwa ruang tunggu belum direnovasi karena anggarannya terbatas.","Mengusulkan perbaikan ruang tunggu dan, sambil menunggu, mengatur jadwal kedatangan supaya ruang tidak penuh."],"s":[4,1,2,3,5],"w":["Tepat, belum ada solusi sementara.","Merugikan warga.","Membela diri.","Sopan, tanpa tindakan.","Ada solusi jangka pendek dan panjang."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3132,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Anda melihat petugas keamanan kantor berbicara kasar kepada warga yang bertanya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menghampiri dan membantu warga itu, lalu menyampaikan masukan kepada petugas keamanan dan koordinatornya secara baik-baik.” Memulihkan layanan dan memperbaiki perilaku.\nPilihan terendah (nilai 1): “Ikut menegur warga supaya petugas keamanan tidak tersinggung.” Memperburuk layanan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Membantu warga itu dan menenangkannya.","Pura-pura tidak melihat.","Melaporkan kejadian itu kepada atasan tanpa membantu warga.","Menghampiri dan membantu warga itu, lalu menyampaikan masukan kepada petugas keamanan dan koordinatornya secara baik-baik.","Ikut menegur warga supaya petugas keamanan tidak tersinggung."],"s":[4,2,3,5,1],"w":["Warga terbantu, perilaku dibiarkan.","Abai.","Prosedural.","Memulihkan layanan dan memperbaiki perilaku.","Memperburuk layanan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3133,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga datang mengurus dokumen yang ternyata menjadi kewenangan instansi lain. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan instansi yang berwenang beserta syarat dan lokasinya, lalu membantu menghubungi kontak instansi itu bila perlu.” Warga tidak tersesat dan terbantu.\nPilihan terendah (nilai 1): “Menerima berkasnya dan berjanji akan meneruskannya sendiri ke instansi yang berwenang, walaupun tidak ada prosedur penerusan berkas seperti itu.” Memberi harapan palsu.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjelaskan instansi yang berwenang beserta syarat dan lokasinya, lalu membantu menghubungi kontak instansi itu bila perlu.","Mengatakan bahwa urusannya bukan di sini.","Memintanya mencari informasi sendiri di internet.","Memberi tahu instansi yang berwenang dan alamatnya.","Menerima berkasnya dan berjanji akan meneruskannya sendiri ke instansi yang berwenang, walaupun tidak ada prosedur penerusan berkas seperti itu."],"s":[5,3,2,4,1],"w":["Warga tidak tersesat dan terbantu.","Benar, minim bantuan.","Lepas tangan.","Informatif.","Memberi harapan palsu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3134,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Anda mengetahui ada pungutan tambahan di unit Anda yang tidak tercantum dalam standar pelayanan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak ikut memungut, mengumpulkan informasi, dan melaporkannya lewat saluran pengaduan atau pengawas internal.” Menghentikan pungli lewat jalur resmi.\nPilihan terendah (nilai 1): “Ikut memungut karena sudah menjadi kebiasaan.” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Ikut memungut karena sudah menjadi kebiasaan.","Tidak ikut memungut dan menegur langsung rekan yang melakukannya, sambil mengingatkan bahwa pungutan itu bisa membuat seluruh unit dilaporkan.","Menghindari loket yang memungut supaya tidak terlibat.","Menolak ikut memungut, mengumpulkan informasi, dan melaporkannya lewat saluran pengaduan atau pengawas internal.","Tidak ikut memungut, tetapi membiarkan praktik itu."],"s":[1,4,2,5,3],"w":["Pungli.","Benar, tetapi praktiknya belum dihentikan lewat jalur resmi.","Menghindar.","Menghentikan pungli lewat jalur resmi.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3135,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Warga mengeluh harus bolak-balik karena tiap petugas memberi informasi syarat yang berbeda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan syarat yang benar kepada warga itu, lalu mengusulkan daftar syarat baku yang disepakati semua petugas dan dipasang di tempat terbuka.” Menghentikan kebingungan dari sumbernya.\nPilihan terendah (nilai 1): “Meminta warga melengkapi semua syarat yang pernah disebut supaya aman.” Membebani warga dengan syarat yang tidak perlu.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjelaskan syarat yang benar kepada warga itu, lalu mengusulkan daftar syarat baku yang disepakati semua petugas dan dipasang di tempat terbuka.","Meminta warga mengikuti informasi dari petugas terakhir.","Meminta warga melengkapi semua syarat yang pernah disebut supaya aman.","Menjelaskan syarat yang benar kepada warga itu.","Mengatakan bahwa itu kesalahan petugas lain."],"s":[5,3,1,4,2],"w":["Menghentikan kebingungan dari sumbernya.","Tidak menyelesaikan masalah.","Membebani warga dengan syarat yang tidak perlu.","Warga terbantu, masalahnya bisa berulang.","Menyalahkan rekan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3136,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga korban banjir kehilangan semua dokumen kependudukannya dan meminta penggantian. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendahulukan pendataannya, memeriksa datanya di sistem, dan memproses penggantian sesuai ketentuan layanan bagi korban bencana.” Cepat dan tetap sesuai aturan.\nPilihan terendah (nilai 1): “Meminta biaya tambahan karena semua dokumen harus dicetak ulang.” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Meminta biaya tambahan karena semua dokumen harus dicetak ulang.","Memintanya membawa surat keterangan kehilangan dari desa dan kepolisian terlebih dahulu, sesuai syarat penggantian dokumen yang biasa.","Memintanya menunggu sampai keadaan normal.","Mendahulukan pendataannya, memeriksa datanya di sistem, dan memproses penggantian sesuai ketentuan layanan bagi korban bencana.","Memproses permohonannya sesuai antrean dengan syarat biasa."],"s":[1,3,2,5,4],"w":["Pungli.","Prosedural dan memberatkan korban bencana.","Menunda.","Cepat dan tetap sesuai aturan.","Benar, kurang peka keadaan darurat."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3137,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga terus menelepon menanyakan hal yang sama, padahal permohonannya masih diproses sesuai jadwal. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan tahapan proses dan perkiraan waktunya, serta memberi tahu cara memantau statusnya sendiri.” Memberi kepastian dan mengurangi kecemasan warga.\nPilihan terendah (nilai 1): “Menegurnya dengan keras karena mengganggu pekerjaan.” Tidak sopan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Tidak lagi mengangkat telepon dari nomornya.","Menegurnya dengan keras karena mengganggu pekerjaan.","Memintanya menunggu kabar dari kantor.","Menjelaskan tahapan proses dan perkiraan waktunya, serta memberi tahu cara memantau statusnya sendiri.","Menjelaskan dengan sabar bahwa permohonannya masih diproses, meminta maaf atas lamanya, dan memintanya menunggu kabar dari kantor."],"s":[2,1,3,5,4],"w":["Menghindar.","Tidak sopan.","Pasif.","Memberi kepastian dan mengurangi kecemasan warga.","Sopan, belum memberi kepastian."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3138,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Anda dipindahkan sementara ke loket layanan yang prosedurnya belum Anda kuasai. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mempelajari prosedurnya dengan cepat, bertanya kepada petugas berpengalaman, dan menyiapkan catatan ringkas supaya layanan tidak tersendat.” Cepat beradaptasi demi layanan.\nPilihan terendah (nilai 1): “Menebak-nebak prosedurnya supaya antrean cepat.” Berisiko merugikan warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Melayani sebisanya sambil menunggu pelatihan resmi.","Bertanya kepada rekan setiap kali menemukan kasus yang tidak dipahami.","Menebak-nebak prosedurnya supaya antrean cepat.","Mempelajari prosedurnya dengan cepat, bertanya kepada petugas berpengalaman, dan menyiapkan catatan ringkas supaya layanan tidak tersendat.","Meminta atasan mengembalikan Anda ke loket lama."],"s":[3,4,1,5,2],"w":["Pasif.","Mau belajar, tetapi layanan bisa tersendat.","Berisiko merugikan warga.","Cepat beradaptasi demi layanan.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3139,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Menjelang batas pendaftaran kerja, banyak warga meminta legalisir dokumen dalam jumlah besar. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengatur antrean khusus legalisir, menyiapkan perlengkapan lebih awal, dan mengusulkan tambahan petugas sementara.” Mengantisipasi lonjakan dengan rapi.\nPilihan terendah (nilai 1): “Meminta \"biaya percepatan\" bagi yang ingin lebih dulu.” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Bekerja lebih cepat dari biasanya.","Mengatur antrean khusus legalisir, menyiapkan perlengkapan lebih awal, dan mengusulkan tambahan petugas sementara.","Membatasi legalisir lima lembar per orang per hari supaya semua warga kebagian, walaupun tidak ada aturan yang mengatur batas itu.","Meminta \"biaya percepatan\" bagi yang ingin lebih dulu.","Melayani sesuai kemampuan dan meminta warga bersabar."],"s":[4,5,2,1,3],"w":["Berusaha, tanpa pengaturan.","Mengantisipasi lonjakan dengan rapi.","Membatasi layanan secara sepihak.","Pungli.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3140,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga meminta Anda mengabaikan satu syarat karena ia mengaku kenal dengan pimpinan Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan dengan sopan bahwa syarat berlaku sama bagi semua warga, lalu membantunya memenuhi syarat itu.” Adil dan tetap membantu.\nPilihan terendah (nilai 1): “Mengabaikan syarat itu demi menjaga hubungan baik dengan pimpinan, karena syarat yang kurang hanya fotokopi yang bisa menyusul.” Nepotisme.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengabaikan syarat itu demi menjaga hubungan baik dengan pimpinan, karena syarat yang kurang hanya fotokopi yang bisa menyusul.","Menjelaskan dengan sopan bahwa syarat berlaku sama bagi semua warga, lalu membantunya memenuhi syarat itu.","Menahan berkasnya sampai ada arahan pimpinan.","Menanyakan dulu kepada pimpinan apakah ia benar kenalannya.","Menolak dan memintanya melengkapi syarat."],"s":[1,5,2,3,4],"w":["Nepotisme.","Adil dan tetap membantu.","Menunda tanpa alasan.","Membuka celah perlakuan khusus.","Tegas, kurang membantu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3141,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Printer di loket Anda rusak sehingga dokumen warga tidak bisa dicetak. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melapor ke petugas teknis, memakai printer cadangan atau milik unit lain untuk sementara, dan memberi tahu warga perkiraan waktunya.” Layanan tetap berjalan.\nPilihan terendah (nilai 1): “Meminta warga membayar biaya cetak di luar kantor.” Membebani dan melanggar standar layanan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Meminta warga datang lagi besok untuk mengambil dokumen.","Melapor ke petugas teknis dan meminta warga menunggu.","Meminta warga membayar biaya cetak di luar kantor.","Melapor ke petugas teknis, memakai printer cadangan atau milik unit lain untuk sementara, dan memberi tahu warga perkiraan waktunya.","Menunggu printer diperbaiki tanpa memberi informasi."],"s":[2,4,1,5,3],"w":["Membebani warga.","Tepat, tetapi layanan tertahan.","Membebani dan melanggar standar layanan.","Layanan tetap berjalan.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3142,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga tidak tahu cara menulis surat permohonan yang menjadi syarat layanan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memberikan contoh format, membantunya menyusun isi sesuai keperluannya, dan memastikan suratnya lengkap.” Memudahkan warga sampai tuntas.\nPilihan terendah (nilai 1): “Membuatkan surat itu dengan meminta imbalan.” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjelaskan secara lisan isi surat yang perlu ditulis.","Menyarankannya memakai jasa pengetikan di depan kantor karena hasilnya lebih rapi dan petugas loket harus melayani warga lain.","Memberikan contoh format surat permohonan.","Memberikan contoh format, membantunya menyusun isi sesuai keperluannya, dan memastikan suratnya lengkap.","Membuatkan surat itu dengan meminta imbalan."],"s":[3,2,4,5,1],"w":["Kurang jelas bagi warga.","Membebani warga.","Membantu, belum memastikan hasilnya.","Memudahkan warga sampai tuntas.","Pungli."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3143,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Banyak dokumen yang sudah jadi menumpuk karena warga belum mengambilnya berminggu-minggu. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menghubungi warga lewat kontak yang tercatat, menawarkan pengiriman bila layanan itu tersedia, dan mendata dokumen yang belum diambil.” Proaktif menuntaskan layanan.\nPilihan terendah (nilai 1): “Memusnahkan dokumen yang terlalu lama tidak diambil.” Merugikan warga dan melanggar aturan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menyimpan dokumen itu sampai warga datang sendiri.","Mengumumkan daftar dokumen yang sudah jadi di papan pengumuman.","Menghubungi warga lewat kontak yang tercatat, menawarkan pengiriman bila layanan itu tersedia, dan mendata dokumen yang belum diambil.","Memindahkan dokumen ke gudang supaya meja rapi.","Memusnahkan dokumen yang terlalu lama tidak diambil."],"s":[3,4,5,2,1],"w":["Pasif.","Informatif, kurang menjangkau warga.","Proaktif menuntaskan layanan.","Mengabaikan.","Merugikan warga dan melanggar aturan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3144,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga mengirim pengaduan tertulis yang sebagian isinya keliru tentang prosedur kantor Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menanggapi dengan sopan, meluruskan bagian yang keliru dengan dasar aturan, dan menindaklanjuti bagian keluhan yang benar.” Adil dan informatif.\nPilihan terendah (nilai 1): “Membalas dengan menyalahkan warga yang tidak membaca aturan.” Tidak sopan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Membalas dengan menyalahkan warga yang tidak membaca aturan.","Tidak membalasnya karena isinya keliru.","Mencatat pengaduan itu dan menunggu arahan.","Menanggapi dengan sopan, meluruskan bagian yang keliru dengan dasar aturan, dan menindaklanjuti bagian keluhan yang benar.","Membalas dengan penjelasan prosedur yang benar."],"s":[1,2,3,5,4],"w":["Tidak sopan.","Mengabaikan.","Pasif.","Adil dan informatif.","Meluruskan, tetapi keluhan yang benar terlewat."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3145,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Ada usulan membuka layanan pada hari Sabtu untuk warga yang bekerja pada hari biasa. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendukung usulan itu dengan mengkaji jumlah peminat, jadwal piket, dan aturan kerja yang berlaku.” Berorientasi pada kebutuhan warga dengan perencanaan.\nPilihan terendah (nilai 1): “Mendukungnya asalkan warga membayar biaya tambahan.” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengikuti keputusan pimpinan saja.","Menolak usulan itu karena pegawai juga butuh waktu istirahat bersama keluarga dan anggaran lembur belum tentu tersedia.","Menyatakan dukungan dalam rapat.","Mendukungnya asalkan warga membayar biaya tambahan.","Mendukung usulan itu dengan mengkaji jumlah peminat, jadwal piket, dan aturan kerja yang berlaku."],"s":[3,2,4,1,5],"w":["Pasif.","Mengutamakan kepentingan pegawai.","Positif, kurang konkret.","Pungli.","Berorientasi pada kebutuhan warga dengan perencanaan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3146,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Anda menemukan dokumen pendukung dari seorang warga yang tampak dipalsukan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak memproses berkas itu, mengamankan dokumennya sesuai prosedur, dan melaporkannya kepada atasan untuk ditindaklanjuti.” Tegas dan sesuai prosedur.\nPilihan terendah (nilai 1): “Memproses berkas itu setelah warga memberi imbalan.” Korupsi.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Tidak memproses berkas itu, mengamankan dokumennya sesuai prosedur, dan melaporkannya kepada atasan untuk ditindaklanjuti.","Mengembalikan berkas tanpa penjelasan.","Meminta warga datang lagi besok tanpa menjelaskan masalahnya.","Menolak memproses berkas dan menjelaskan bahwa dokumennya perlu diperiksa.","Memproses berkas itu setelah warga memberi imbalan."],"s":[5,3,2,4,1],"w":["Tegas dan sesuai prosedur.","Tidak ditindaklanjuti.","Menunda.","Tepat, belum dilaporkan.","Korupsi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3147,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga meminta pengurusan paspornya dipercepat karena harus segera berobat ke luar negeri. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memeriksa ketentuan layanan percepatan, membantunya melengkapi bukti yang diperlukan, dan memprosesnya sesuai aturan.” Peka keadaan dan tetap sesuai aturan.\nPilihan terendah (nilai 1): “Mendahulukannya dengan imbalan di luar biaya resmi.” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjelaskan bahwa ada layanan percepatan beserta syaratnya.","Mendahulukannya dengan imbalan di luar biaya resmi.","Memprosesnya sesuai antrean biasa.","Memeriksa ketentuan layanan percepatan, membantunya melengkapi bukti yang diperlukan, dan memprosesnya sesuai aturan.","Menyarankannya menunda keberangkatan sampai paspornya selesai sesuai antrean biasa, karena semua pemohon juga punya kepentingan mendesak."],"s":[4,1,3,5,2],"w":["Informatif.","Pungli.","Tidak memperhatikan keadaan.","Peka keadaan dan tetap sesuai aturan.","Membebani warga yang sedang sakit."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3148,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga dari desa yang jauh datang mengambil dokumen, tetapi pejabat yang harus menandatanganinya sedang dinas luar. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memeriksa apakah ada pejabat pengganti atau tanda tangan elektronik yang sah; bila tidak ada, menawarkan pengiriman dokumen agar warga tidak perlu datang lagi.” Mencari solusi sah supaya warga tidak dirugikan.\nPilihan terendah (nilai 1): “Menandatangani dokumen itu atas nama pejabat tanpa wewenang.” Pemalsuan tanda tangan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menandatangani dokumen itu atas nama pejabat tanpa wewenang.","Memintanya menunggu sampai sore tanpa kepastian.","Memintanya kembali setelah pejabat itu pulang.","Memeriksa apakah ada pejabat pengganti atau tanda tangan elektronik yang sah; bila tidak ada, menawarkan pengiriman dokumen agar warga tidak perlu datang lagi.","Meminta maaf dan memastikan dokumennya siap esok hari."],"s":[1,2,3,5,4],"w":["Pemalsuan tanda tangan.","Membuang waktu warga.","Pasif.","Mencari solusi sah supaya warga tidak dirugikan.","Sopan, tetapi warga tetap harus kembali."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3149,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Tetangga Anda meminta dimasukkan ke daftar penerima bantuan sosial, padahal ia tidak memenuhi kriteria. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan kriteria penerima dengan sopan dan tetap mendata sesuai fakta, sambil memberi tahu program lain yang mungkin cocok.” Adil dan tetap membantu.\nPilihan terendah (nilai 1): “Memasukkan namanya karena merasa tidak enak.” Penyalahgunaan wewenang.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menghindari tetangga itu supaya tidak ditanya lagi.","Memasukkan namanya karena merasa tidak enak.","Mencatat namanya dan menyerahkan keputusan kepada tim verifikasi.","Menolak dengan sopan karena ia tidak memenuhi kriteria.","Menjelaskan kriteria penerima dengan sopan dan tetap mendata sesuai fakta, sambil memberi tahu program lain yang mungkin cocok."],"s":[2,1,3,4,5],"w":["Menghindar.","Penyalahgunaan wewenang.","Melempar keputusan yang sudah jelas.","Benar, tanpa alternatif.","Adil dan tetap membantu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3150,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Kantor Anda mendapat ulasan bintang satu di peta daring karena petugasnya dianggap tidak ramah. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membalas ulasan dengan sopan, menanyakan detail kejadian, dan membahas perbaikan sikap pelayanan bersama tim.” Terbuka pada kritik dan memperbaiki diri.\nPilihan terendah (nilai 1): “Meminta teman dan keluarga memberi ulasan bintang lima supaya nilai kantor naik dan ulasan buruk itu tidak terlihat lagi oleh warga lain.” Manipulasi penilaian.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengabaikannya karena ulasan daring tidak penting.","Membalas ulasan itu dengan permintaan maaf.","Membalas ulasan dengan sopan, menanyakan detail kejadian, dan membahas perbaikan sikap pelayanan bersama tim.","Melaporkan ulasan itu kepada atasan.","Meminta teman dan keluarga memberi ulasan bintang lima supaya nilai kantor naik dan ulasan buruk itu tidak terlihat lagi oleh warga lain."],"s":[2,4,5,3,1],"w":["Mengabaikan kritik.","Sopan, belum ada perbaikan.","Terbuka pada kritik dan memperbaiki diri.","Prosedural.","Manipulasi penilaian."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3151,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga datang dalam keadaan mabuk dan berteriak-teriak di ruang layanan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tetap tenang, menjauhkannya dari warga lain dengan bantuan petugas keamanan, dan melayaninya setelah ia tenang.” Menjaga keamanan dan tetap melayani.\nPilihan terendah (nilai 1): “Membalas berteriak dan mengusirnya dengan kasar.” Memperkeruh suasana.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menutup loket sementara sampai warga itu pergi, supaya petugas dan warga lain tidak menjadi sasaran kemarahannya.","Tetap tenang, menjauhkannya dari warga lain dengan bantuan petugas keamanan, dan melayaninya setelah ia tenang.","Meminta petugas keamanan menenangkannya.","Membalas berteriak dan mengusirnya dengan kasar.","Membiarkannya sampai ia diam sendiri."],"s":[2,5,4,1,3],"w":["Merugikan warga lain.","Menjaga keamanan dan tetap melayani.","Tepat, belum memastikan layanannya.","Memperkeruh suasana.","Pasif dan mengganggu warga lain."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3152,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang ibu dengan balita yang rewel harus menunggu lama di antrean. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengecek apakah ia termasuk kelompok prioritas sesuai ketentuan, menyediakan tempat duduk yang nyaman, dan memberi perkiraan waktu layanan.” Peka dan tetap adil.\nPilihan terendah (nilai 1): “Menegurnya karena anaknya mengganggu warga lain.” Tidak berempati.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Membiarkannya sesuai antrean tanpa perhatian khusus.","Mengecek apakah ia termasuk kelompok prioritas sesuai ketentuan, menyediakan tempat duduk yang nyaman, dan memberi perkiraan waktu layanan.","Menyarankannya datang lagi tanpa membawa anak.","Menegurnya karena anaknya mengganggu warga lain.","Menawarkan tempat duduk yang lebih nyaman."],"s":[3,5,2,1,4],"w":["Pasif.","Peka dan tetap adil.","Membebani warga.","Tidak berempati.","Peduli, hak prioritasnya belum dicek."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3153,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga meminta Anda menahan berkas tetangganya yang sedang berselisih dengannya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan tegas karena setiap berkas diproses sesuai aturan, dan menyarankannya menyelesaikan perselisihan lewat jalur yang tepat.” Netral dan adil.\nPilihan terendah (nilai 1): “Menahan berkas itu karena ia memberi imbalan.” Penyalahgunaan wewenang.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menahan berkas itu karena ia memberi imbalan.","Menolak permintaan itu.","Menolak dengan tegas karena setiap berkas diproses sesuai aturan, dan menyarankannya menyelesaikan perselisihan lewat jalur yang tepat.","Mendengarkan ceritanya tanpa menanggapi.","Menjawab akan mempertimbangkannya supaya ia cepat pergi."],"s":[1,4,5,3,2],"w":["Penyalahgunaan wewenang.","Tepat, tanpa saran.","Netral dan adil.","Pasif.","Memberi harapan keliru."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3154,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga datang tepat saat jam istirahat siang Anda dimulai, sementara petugas pengganti belum siap. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melayaninya lebih dulu bila urusannya singkat, atau memastikan petugas pengganti siap sebelum Anda beristirahat.” Layanan tidak terputus.\nPilihan terendah (nilai 1): “Menutup loket lebih awal sebelum jam istirahat.” Melanggar jam layanan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memintanya menunggu sebentar sampai petugas pengganti datang.","Langsung pergi istirahat tanpa berkata apa-apa.","Memberi tahu bahwa jam istirahat sudah dimulai dan memintanya kembali satu jam lagi, sambil mempersilakannya menunggu di ruang tunggu.","Melayaninya lebih dulu bila urusannya singkat, atau memastikan petugas pengganti siap sebelum Anda beristirahat.","Menutup loket lebih awal sebelum jam istirahat."],"s":[4,2,3,5,1],"w":["Wajar, tetapi warga menunggu.","Mengabaikan warga.","Prosedural.","Layanan tidak terputus.","Melanggar jam layanan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3155,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga mengeluh nomor antrean daring yang sudah dipesannya tidak diakui petugas. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengecek pesanannya di sistem, melayaninya sesuai nomor itu bila valid, dan melaporkan kendala sistem ke bagian TI.” Adil dan memperbaiki sistem.\nPilihan terendah (nilai 1): “Menyalahkan warga karena dianggap salah memakai aplikasi.” Menyalahkan warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengecek pesanannya di sistem, melayaninya sesuai nomor itu bila valid, dan melaporkan kendala sistem ke bagian TI.","Mengecek pesanannya di sistem lalu melayaninya, tanpa menelusuri mengapa nomornya tidak terbaca oleh petugas di pintu masuk.","Memintanya mengambil nomor antrean baru di tempat.","Mengatakan antrean daring bukan urusan loket.","Menyalahkan warga karena dianggap salah memakai aplikasi."],"s":[5,4,3,2,1],"w":["Adil dan memperbaiki sistem.","Tuntas untuk warga itu, kendalanya tidak dilaporkan.","Tidak menyelesaikan masalah.","Lepas tangan.","Menyalahkan warga."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3156,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang wartawan menanyakan kepada Anda soal keluhan warga terhadap layanan kantor Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan bahwa pernyataan resmi disampaikan bagian humas, lalu membantu wartawan terhubung dengan humas.” Tertib informasi dan tetap kooperatif.\nPilihan terendah (nilai 1): “Memberikan pernyataan pribadi yang menyalahkan atasan.” Tidak etis dan tidak berwenang.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengarahkan wartawan ke bagian humas.","Menolak berkomentar tanpa penjelasan.","Menyampaikan bahwa pernyataan resmi disampaikan bagian humas, lalu membantu wartawan terhubung dengan humas.","Memberikan pernyataan pribadi yang menyalahkan atasan.","Menghindari wartawan dengan berpura-pura sibuk."],"s":[4,3,5,1,2],"w":["Tepat, kurang membantu.","Kurang komunikatif.","Tertib informasi dan tetap kooperatif.","Tidak etis dan tidak berwenang.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3157,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga menitipkan berkas tetangganya kepada Anda, padahal aturannya harus diajukan sendiri atau dengan surat kuasa. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan aturan pengajuan dengan sopan, memberi contoh surat kuasa, dan mencatat supaya tetangganya bisa langsung dilayani saat datang.” Taat aturan dan memudahkan.\nPilihan terendah (nilai 1): “Memproses berkas titipan itu tanpa surat kuasa.” Melanggar prosedur.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memproses berkas titipan itu tanpa surat kuasa.","Menjelaskan aturan pengajuan dengan sopan, memberi contoh surat kuasa, dan mencatat supaya tetangganya bisa langsung dilayani saat datang.","Menolak titipan itu dan menjelaskan aturannya.","Menolak tanpa penjelasan.","Menerima titipannya dan menunggu pemiliknya datang."],"s":[1,5,4,2,3],"w":["Melanggar prosedur.","Taat aturan dan memudahkan.","Tepat.","Tidak informatif.","Tidak sesuai aturan pengajuan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3158,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga penyandang tunarungu datang ke loket dan kesulitan berkomunikasi secara lisan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Berkomunikasi lewat tulisan atau gambar dengan sabar, memastikan ia memahami prosesnya, dan mengusulkan layanan juru bahasa isyarat.” Inklusif dan tuntas.\nPilihan terendah (nilai 1): “Melayaninya dengan nada tinggi karena ia tidak segera paham.” Tidak sopan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memberinya formulir dan memintanya mengisi sendiri.","Berkomunikasi lewat tulisan dengan sabar.","Melayaninya dengan nada tinggi karena ia tidak segera paham.","Berkomunikasi lewat tulisan atau gambar dengan sabar, memastikan ia memahami prosesnya, dan mengusulkan layanan juru bahasa isyarat.","Memintanya kembali bersama pendamping."],"s":[3,4,1,5,2],"w":["Bantuan minimal.","Membantu, belum ada perbaikan layanan.","Tidak sopan.","Inklusif dan tuntas.","Menunda layanan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3159,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga bertanya tentang syarat layanan lewat pesan di akun media sosial kantor yang Anda kelola. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjawab dengan jelas dan cepat, melampirkan daftar syarat resmi, dan menanyakan apakah masih ada yang kurang jelas.” Responsif dan tuntas.\nPilihan terendah (nilai 1): “Membalas dengan meminta \"biaya informasi\".” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjawab dengan daftar syarat singkat.","Membalas dengan meminta \"biaya informasi\".","Memintanya datang ke kantor untuk bertanya langsung supaya penjelasannya lebih lengkap dan tidak terjadi salah paham lewat pesan.","Membiarkan pesannya karena kantor sedang ramai.","Menjawab dengan jelas dan cepat, melampirkan daftar syarat resmi, dan menanyakan apakah masih ada yang kurang jelas."],"s":[4,1,3,2,5],"w":["Informatif.","Pungli.","Kurang memudahkan.","Menunda.","Responsif dan tuntas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3160,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Pimpinan meminta Anda menyusun standar pelayanan yang mudah dipahami warga. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyusunnya bersama petugas loket dan perwakilan warga dengan bahasa sederhana, lalu mengujinya kepada beberapa warga.” Partisipatif dan tepat sasaran.\nPilihan terendah (nilai 1): “Menyusun standar yang menguntungkan petugas, misalnya jam layanan yang dipersingkat.” Mengutamakan kepentingan sendiri.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menyusunnya bersama petugas loket dan perwakilan warga dengan bahasa sederhana, lalu mengujinya kepada beberapa warga.","Menyusunnya sendiri dengan bahasa sederhana sesuai aturan.","Menyalin standar pelayanan dari instansi lain.","Menyusun standar yang menguntungkan petugas, misalnya jam layanan yang dipersingkat.","Menundanya karena masih banyak pekerjaan lain."],"s":[5,4,3,1,2],"w":["Partisipatif dan tepat sasaran.","Baik, belum melibatkan pengguna layanan.","Belum tentu sesuai kebutuhan.","Mengutamakan kepentingan sendiri.","Menunda."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3161,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga datang dalam keadaan sakit dan tampak tidak kuat mengantre lama. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memberinya tempat duduk, mengecek apakah ia berhak atas layanan prioritas, dan melayaninya secepat yang diizinkan aturan.” Berempati dan sesuai aturan.\nPilihan terendah (nilai 1): “Menegurnya karena datang dalam keadaan sakit.” Tidak berempati.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Membiarkannya mengantre seperti biasa.","Menyarankannya pulang dan kembali setelah sehat.","Memberinya tempat duduk sambil menunggu giliran.","Menegurnya karena datang dalam keadaan sakit.","Memberinya tempat duduk, mengecek apakah ia berhak atas layanan prioritas, dan melayaninya secepat yang diizinkan aturan."],"s":[3,2,4,1,5],"w":["Pasif.","Menunda layanan.","Peduli, belum tuntas.","Tidak berempati.","Berempati dan sesuai aturan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3162,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Banyak warga tidak memahami istilah teknis di formulir permohonan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan istilah itu kepada warga yang bertanya dan mengusulkan revisi formulir dengan bahasa yang lebih sederhana.” Membantu dan memperbaiki formulir.\nPilihan terendah (nilai 1): “Mengisikan formulir warga dengan memungut biaya jasa.” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menempelkan contoh formulir yang sudah terisi di dinding ruang tunggu supaya warga bisa mencontoh sendiri tanpa bertanya.","Menjelaskan istilah itu kepada warga yang bertanya dan mengusulkan revisi formulir dengan bahasa yang lebih sederhana.","Menjelaskan istilahnya kepada setiap warga yang bertanya.","Menganggap warga seharusnya sudah paham.","Mengisikan formulir warga dengan memungut biaya jasa."],"s":[3,5,4,2,1],"w":["Sedikit membantu.","Membantu dan memperbaiki formulir.","Membantu, masalahnya berulang.","Mengabaikan.","Pungli."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3163,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Jam layanan sudah berakhir, tetapi masih ada beberapa warga yang sudah memegang nomor antrean dan belum terlayani. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tetap melayani warga yang sudah mengantre sesuai ketentuan, dan memberi tahu warga yang datang setelahnya.” Adil bagi yang sudah mengantre.\nPilihan terendah (nilai 1): “Hanya melayani warga yang memberi uang lembur.” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Pulang dan meminta petugas keamanan memberi tahu warga.","Menutup layanan dan meminta semua warga yang tersisa datang besok.","Tetap melayani warga yang sudah mengantre sesuai ketentuan, dan memberi tahu warga yang datang setelahnya.","Melayani sebagian warga sampai batas waktu yang diizinkan, lalu meminta sisanya datang besok pagi dan mendahulukan mereka.","Hanya melayani warga yang memberi uang lembur."],"s":[2,3,5,4,1],"w":["Menghindar.","Pasif.","Adil bagi yang sudah mengantre.","Membantu sebagian.","Pungli."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3164,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga memotong antrean sehingga warga lain protes. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Dengan sopan memintanya kembali ke urutan sesuai nomor antrean, menjelaskan aturannya, dan menenangkan warga lain.” Adil dan menjaga ketertiban.\nPilihan terendah (nilai 1): “Melayaninya lebih dulu dan meminta warga lain diam.” Tidak adil.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memintanya mengambil nomor antrean.","Pura-pura tidak melihat supaya tidak terjadi keributan.","Melayaninya lebih dulu dan meminta warga lain diam.","Dengan sopan memintanya kembali ke urutan sesuai nomor antrean, menjelaskan aturannya, dan menenangkan warga lain.","Membiarkan petugas keamanan yang menanganinya."],"s":[4,2,1,5,3],"w":["Adil, kurang menenangkan.","Menghindar.","Tidak adil.","Adil dan menjaga ketertiban.","Melempar tanggung jawab."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3165,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Warga meminta tanda terima atas berkas yang mereka serahkan, tetapi kantor Anda belum punya format tanda terima. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membuatkan tanda terima sementara yang memuat daftar berkas dan tanggal, lalu mengusulkan format resmi kepada atasan.” Akuntabel dan memperbaiki prosedur.\nPilihan terendah (nilai 1): “Menolak menerima berkas bila warga terus meminta tanda terima.” Mempersulit warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menuliskan bukti penerimaan sederhana untuk warga.","Menjelaskan bahwa kantor tidak menyediakan tanda terima.","Membuatkan tanda terima sementara yang memuat daftar berkas dan tanggal, lalu mengusulkan format resmi kepada atasan.","Menolak menerima berkas bila warga terus meminta tanda terima.","Memintanya memotret berkasnya sendiri sebagai bukti."],"s":[4,3,5,1,2],"w":["Membantu, belum dibakukan.","Kaku.","Akuntabel dan memperbaiki prosedur.","Mempersulit warga.","Lepas tangan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3166,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Warga mengeluh harus memfotokopi berkas di tempat yang jauh dari kantor. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengusulkan layanan fotokopi atau pemindaian di kantor, dan sementara itu menerima berkas digital bila aturan membolehkan.” Memudahkan warga.\nPilihan terendah (nilai 1): “Menawarkan jasa fotokopi pribadi dengan tarif tinggi.” Memanfaatkan jabatan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menganggap itu urusan warga sendiri.","Menawarkan jasa fotokopi pribadi dengan tarif tinggi.","Mengusulkan penyediaan mesin fotokopi di kantor.","Memberi tahu lokasi fotokopi terdekat.","Mengusulkan layanan fotokopi atau pemindaian di kantor, dan sementara itu menerima berkas digital bila aturan membolehkan."],"s":[2,1,4,3,5],"w":["Tidak peduli.","Memanfaatkan jabatan.","Baik, belum ada solusi sementara.","Informatif.","Memudahkan warga."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3167,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga memaksa membayar karena mengira layanan itu berbayar, padahal gratis. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak uangnya, menjelaskan bahwa layanan itu gratis, dan menunjukkan standar pelayanan sebagai buktinya.” Jujur dan mengedukasi.\nPilihan terendah (nilai 1): “Menerima uangnya karena warga sendiri yang memberi.” Gratifikasi.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menerima uangnya untuk sementara supaya warga tidak tersinggung, lalu berniat mengembalikannya kalau ia datang lagi.","Menerima uangnya karena warga sendiri yang memberi.","Menolak uangnya, menjelaskan bahwa layanan itu gratis, dan menunjukkan standar pelayanan sebagai buktinya.","Menolak uangnya tanpa penjelasan.","Menolak uangnya dan menjelaskan bahwa layanan itu gratis."],"s":[2,1,5,3,4],"w":["Tidak tegas.","Gratifikasi.","Jujur dan mengedukasi.","Warga tetap bingung.","Tepat."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3168,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga salah paham dan menuduh Anda sengaja mempersulit urusannya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tetap tenang, mendengarkan keberatannya, menjelaskan prosedur dan alasannya, lalu membantunya melengkapi syarat yang kurang.” Meredakan dan menyelesaikan.\nPilihan terendah (nilai 1): “Membalas tuduhannya dengan nada tinggi.” Tidak profesional.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Membalas tuduhannya dengan nada tinggi.","Menjelaskan prosedur dan alasannya dengan sopan.","Diam dan membiarkannya marah.","Tetap tenang, mendengarkan keberatannya, menjelaskan prosedur dan alasannya, lalu membantunya melengkapi syarat yang kurang.","Memintanya mengurus di loket lain."],"s":[1,4,3,5,2],"w":["Tidak profesional.","Meluruskan, belum membantu.","Pasif.","Meredakan dan menyelesaikan.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3169,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Anda menemukan berkas seorang warga terselip dan belum diproses selama seminggu. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Segera memproses berkas itu, menghubungi warga untuk meminta maaf dan memberi kepastian, serta memperbaiki cara penyimpanan berkas.” Bertanggung jawab dan mencegah terulang.\nPilihan terendah (nilai 1): “Mengubah tanggal penerimaan berkas supaya keterlambatan tidak terlihat.” Tidak jujur.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Segera memproses berkas itu.","Mengubah tanggal penerimaan berkas supaya keterlambatan tidak terlihat.","Segera memproses berkas itu, menghubungi warga untuk meminta maaf dan memberi kepastian, serta memperbaiki cara penyimpanan berkas.","Memasukkannya ke antrean berkas biasa.","Menunggu warga menanyakan berkasnya."],"s":[4,1,5,3,2],"w":["Diperbaiki, tanpa komunikasi kepada warga.","Tidak jujur.","Bertanggung jawab dan mencegah terulang.","Warga dirugikan lebih lama.","Menunda."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3170,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga ingin mengadukan petugas yang meminta pungutan liar, tetapi ia takut identitasnya diketahui. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan saluran pengaduan yang menjamin kerahasiaan pelapor, membantunya menyusun laporan, dan memastikan laporan itu diteruskan.” Melindungi pelapor dan menindaklanjuti pungli.\nPilihan terendah (nilai 1): “Memberi tahu petugas itu bahwa ada warga yang akan melaporkannya.” Membocorkan identitas pelapor.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menjelaskan saluran pengaduan yang menjamin kerahasiaan pelapor, membantunya menyusun laporan, dan memastikan laporan itu diteruskan.","Memberi tahu petugas itu bahwa ada warga yang akan melaporkannya.","Memintanya melapor langsung kepada atasan petugas itu.","Menyarankannya melupakan saja supaya tidak repot.","Memberikan alamat kanal pengaduan resmi."],"s":[5,1,3,2,4],"w":["Melindungi pelapor dan menindaklanjuti pungli.","Membocorkan identitas pelapor.","Kurang menjamin kerahasiaan.","Menghambat pengaduan.","Membantu, kurang pendampingan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3171,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga meminta Anda menerima berkasnya di rumah Anda supaya ia tidak perlu mengantre di kantor. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan sopan, menjelaskan bahwa berkas hanya diterima lewat kanal resmi, dan memberi tahu layanan daring atau jadwal kantor yang sepi.” Tertib aturan dan tetap memudahkan.\nPilihan terendah (nilai 1): “Menerima berkasnya di rumah dengan imbalan uang lelah.” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menolak dan memintanya datang ke kantor.","Menjawab nanti dipikirkan supaya ia tidak bertanya lagi.","Memintanya menitipkan berkas kepada keluarga Anda saja.","Menolak dengan sopan, menjelaskan bahwa berkas hanya diterima lewat kanal resmi, dan memberi tahu layanan daring atau jadwal kantor yang sepi.","Menerima berkasnya di rumah dengan imbalan uang lelah."],"s":[4,2,3,5,1],"w":["Tepat, kurang memberi alternatif.","Menghindar.","Melanggar prosedur secara halus.","Tertib aturan dan tetap memudahkan.","Pungli."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3172,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Pemerintah meluncurkan layanan baru yang memudahkan warga, tetapi masih sedikit warga yang mengetahuinya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyosialisasikannya lewat loket, media sosial, dan tokoh masyarakat, lalu memantau jumlah warga yang memakainya.” Informasi menjangkau warga.\nPilihan terendah (nilai 1): “Merahasiakan layanan itu supaya pekerjaan tidak bertambah.” Menghambat hak warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menunggu instruksi sosialisasi dari pusat.","Menyosialisasikannya lewat loket, media sosial, dan tokoh masyarakat, lalu memantau jumlah warga yang memakainya.","Menempelkan pengumuman layanan baru di papan kantor.","Merahasiakan layanan itu supaya pekerjaan tidak bertambah.","Menjelaskan layanan itu hanya kepada warga yang bertanya, karena pengumuman resmi biasanya dibuat oleh bagian humas di kantor pusat."],"s":[2,5,4,1,3],"w":["Menunda.","Informasi menjangkau warga.","Informatif, jangkauannya terbatas.","Menghambat hak warga.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3173,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Warga mengeluhkan juru parkir liar yang memungut biaya di halaman kantor Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkannya kepada pengelola gedung dan aparat terkait, lalu memastikan warga tahu bahwa parkir di kantor tidak dipungut biaya.” Melindungi warga dan menertibkan.\nPilihan terendah (nilai 1): “Membiarkannya karena juru parkir itu memberi setoran kepada sebagian pegawai.” Membiarkan pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Membiarkannya karena juru parkir itu memberi setoran kepada sebagian pegawai.","Melaporkannya kepada pengelola gedung.","Menyarankan warga tidak membayar.","Menganggap itu bukan urusan kantor.","Melaporkannya kepada pengelola gedung dan aparat terkait, lalu memastikan warga tahu bahwa parkir di kantor tidak dipungut biaya."],"s":[1,4,3,2,5],"w":["Membiarkan pungli.","Tepat, warga belum diberi tahu.","Tidak menyelesaikan.","Abai.","Melindungi warga dan menertibkan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3174,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga meminta bantuan untuk urusan yang sama sekali bukan tugas instansi Anda, misalnya mengisi formulir bank. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan dengan ramah bahwa urusan itu di luar layanan instansi, memberi tahu tempat yang tepat, dan membantu sebatas tidak mengganggu layanan lain.” Ramah dan tetap fokus pada tugas.\nPilihan terendah (nilai 1): “Membantunya di jam layanan dengan meminta imbalan.” Pungli dan mengganggu layanan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memberi tahu tempat yang tepat untuk urusannya.","Memintanya menunggu sampai antrean selesai tanpa kepastian.","Menjelaskan dengan ramah bahwa urusan itu di luar layanan instansi, memberi tahu tempat yang tepat, dan membantu sebatas tidak mengganggu layanan lain.","Membantunya di jam layanan dengan meminta imbalan.","Mengatakan bahwa itu bukan urusan kantor."],"s":[4,2,5,1,3],"w":["Informatif.","Menunda.","Ramah dan tetap fokus pada tugas.","Pungli dan mengganggu layanan.","Benar, kurang ramah."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3175,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga di desa dengan sinyal internet lemah gagal mendaftar layanan daring berkali-kali. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membantunya mendaftar dari kantor, mencatat kendala jaringan di wilayahnya, dan mengusulkan pendaftaran luring untuk daerah serupa.” Menyelesaikan kasusnya dan memperbaiki layanan.\nPilihan terendah (nilai 1): “Menyalahkan warga karena tinggal di daerah terpencil.” Diskriminatif.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Membantunya mendaftar dari kantor, mencatat kendala jaringan di wilayahnya, dan mengusulkan pendaftaran luring untuk daerah serupa.","Membantunya mendaftar dari komputer kantor.","Menyalahkan warga karena tinggal di daerah terpencil.","Menyarankannya mencoba lagi pada malam hari.","Memintanya mencari tempat yang sinyalnya bagus."],"s":[5,4,1,3,2],"w":["Menyelesaikan kasusnya dan memperbaiki layanan.","Tuntas untuk warga itu.","Diskriminatif.","Belum tentu berhasil.","Lepas tangan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3176,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga selalu datang paling pagi, tetapi berkasnya sering tidak lengkap sehingga ia harus pulang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membuatkan daftar periksa syarat yang jelas untuknya dan memeriksa kelengkapan berkasnya bersama sebelum ia mengantre.” Mencegah warga bolak-balik.\nPilihan terendah (nilai 1): “Menolak melayaninya lagi karena dianggap merepotkan.” Diskriminatif.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menolak melayaninya lagi karena dianggap merepotkan.","Menjelaskan ulang syarat yang kurang setiap kali ia datang.","Menyarankannya memakai jasa pengurusan berkas di sekitar kantor supaya tidak perlu bolak-balik setiap kali ada syarat yang kurang.","Memintanya membaca syarat di papan pengumuman.","Membuatkan daftar periksa syarat yang jelas untuknya dan memeriksa kelengkapan berkasnya bersama sebelum ia mengantre."],"s":[1,4,2,3,5],"w":["Diskriminatif.","Membantu, tetapi masalahnya berulang.","Membebani warga dan mendorong ke calo.","Kurang membantu.","Mencegah warga bolak-balik."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3177,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Hasil pemeriksaan menunjukkan sebagian warga harus menunggu lebih dari dua jam hanya untuk menyerahkan berkas. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengusulkan loket khusus penyerahan berkas atau pendaftaran daring, lalu mengukur ulang waktu tunggunya setelah diterapkan.” Perbaikan berbasis data.\nPilihan terendah (nilai 1): “Mengubah catatan waktu tunggu supaya terlihat singkat.” Memanipulasi data.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengusulkan loket khusus penyerahan berkas atau pendaftaran daring, lalu mengukur ulang waktu tunggunya setelah diterapkan.","Mengubah catatan waktu tunggu supaya terlihat singkat.","Mencatat temuan itu untuk laporan bulanan.","Menganggapnya wajar karena berkas memang banyak.","Mengusulkan tambahan petugas pada jam-jam sibuk dan meminta petugas loket bekerja lebih cepat saat antrean panjang."],"s":[5,1,3,2,4],"w":["Perbaikan berbasis data.","Memanipulasi data.","Pasif.","Membela diri.","Membantu, belum menyentuh alurnya."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3178,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga lanjut usia meminta dokumennya diantarkan karena ia sakit dan tidak bisa datang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengecek layanan antar atau jemput bola yang tersedia, mengatur pengirimannya, dan memastikan dokumen sampai kepada orang yang berhak.” Peka dan aman.\nPilihan terendah (nilai 1): “Mengantar dokumennya sendiri dengan meminta ongkos di luar ketentuan.” Pungli.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Mengantar dokumennya sendiri dengan meminta ongkos di luar ketentuan.","Memintanya datang sendiri setelah sembuh.","Menawarkan agar keluarganya mengambil dengan surat kuasa.","Menyimpan dokumennya tanpa kabar.","Mengecek layanan antar atau jemput bola yang tersedia, mengatur pengirimannya, dan memastikan dokumen sampai kepada orang yang berhak."],"s":[1,3,4,2,5],"w":["Pungli.","Kaku.","Solutif sesuai aturan.","Menunda.","Peka dan aman."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3179,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Instansi Anda memberlakukan pengajuan daring, tetapi seorang warga tetap datang ke kantor karena tidak paham caranya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membantunya mengajukan secara daring di kantor sambil mengajarinya langkah-langkahnya.” Melayani sekaligus mengedukasi.\nPilihan terendah (nilai 1): “Menolaknya karena layanan tatap muka sudah ditiadakan.” Kaku dan merugikan warga.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Memberinya selebaran panduan pengajuan daring dan memintanya mempraktikkan sendiri di rumah dengan bantuan keluarga.","Menolaknya karena layanan tatap muka sudah ditiadakan.","Memintanya pulang dan mencoba sendiri di rumah.","Membantunya mengajukan secara daring di kantor sambil mengajarinya langkah-langkahnya.","Membantu mengajukan secara daring tanpa menjelaskan caranya."],"s":[3,1,2,5,4],"w":["Informatif, kurang cocok untuknya.","Kaku dan merugikan warga.","Lepas tangan.","Melayani sekaligus mengedukasi.","Tuntas, tetapi warga tetap bergantung."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3180,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga melaporkan jalan rusak kepada Anda, padahal Anda bertugas di bagian kependudukan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mencatat laporannya, meneruskannya ke unit atau instansi yang berwenang, dan memberi tahu warga cara memantau tindak lanjutnya.” Tidak melempar warga dan memastikan laporan sampai.\nPilihan terendah (nilai 1): “Menertawakan laporannya karena salah alamat.” Tidak sopan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menertawakan laporannya karena salah alamat.","Memintanya melapor sendiri ke media sosial.","Mengatakan bahwa itu bukan urusan bagian Anda.","Mencatat laporannya, meneruskannya ke unit atau instansi yang berwenang, dan memberi tahu warga cara memantau tindak lanjutnya.","Memberi tahu instansi yang menangani jalan dan kontaknya."],"s":[1,2,3,5,4],"w":["Tidak sopan.","Lepas tangan.","Benar, kurang membantu.","Tidak melempar warga dan memastikan laporan sampai.","Informatif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3181,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang petugas magang di unit Anda keliru memberi informasi syarat kepada beberapa warga. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menghubungi warga yang terdampak untuk meluruskan informasi, lalu membimbing petugas magang itu dan memastikan ia memegang daftar syarat yang benar.” Memulihkan layanan dan mencegah terulang.\nPilihan terendah (nilai 1): “Menyalahkan petugas magang di depan warga.” Mempermalukan rekan.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menghubungi warga yang terdampak untuk meluruskan informasi, lalu membimbing petugas magang itu dan memastikan ia memegang daftar syarat yang benar.","Menyalahkan petugas magang di depan warga.","Menegur petugas magang dan memberinya daftar syarat yang benar.","Membiarkannya karena ia hanya magang.","Melaporkan kesalahan itu kepada atasan."],"s":[5,1,4,2,3],"w":["Memulihkan layanan dan mencegah terulang.","Mempermalukan rekan.","Mencegah terulang, warga belum dihubungi.","Abai.","Prosedural."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3182,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga meminta Anda mengubah data tanggal lahirnya supaya memenuhi syarat usia sebuah lowongan kerja. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan tegas dan menjelaskan bahwa data hanya boleh diubah berdasarkan dokumen sah.” Menjaga kebenaran data.\nPilihan terendah (nilai 1): “Mengubah datanya karena kasihan ia sangat membutuhkan pekerjaan dan selisih usianya hanya beberapa bulan dari batas lowongan.” Pemalsuan data.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menolak dengan tegas dan menjelaskan bahwa data hanya boleh diubah berdasarkan dokumen sah.","Menolak permintaan itu.","Memintanya membawa surat pengantar dari kelurahan dulu.","Mengubah datanya karena kasihan ia sangat membutuhkan pekerjaan dan selisih usianya hanya beberapa bulan dari batas lowongan.","Menjawab akan menanyakannya kepada atasan supaya ia pergi."],"s":[5,4,3,1,2],"w":["Menjaga kebenaran data.","Tepat, tanpa penjelasan.","Memberi kesan bisa diatur.","Pemalsuan data.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."},{"i":3183,"k":"skd.tkp.pelayanan-publik","j":"situasi","v":2,"q":"Seorang warga berkebutuhan khusus datang dengan kursi roda, tetapi loket berada di lantai dua tanpa lift. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melayaninya di lantai satu dengan membawa perlengkapan yang dibutuhkan, lalu mengusulkan loket ramah disabilitas di lantai dasar.” Inklusif dan memperbaiki fasilitas.\nPilihan terendah (nilai 1): “Memintanya mengurus lewat calo saja.” Mengarahkan ke praktik tidak resmi.\nPrinsip aspek pelayanan publik: ASN melayani dengan ramah, cepat, tuntas, adil, dan tanpa pungutan di luar aturan; keluhan warga diselesaikan, bukan dihindari.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan.","o":["Menyarankannya datang lagi bersama keluarga yang bisa membantunya naik.","Melayaninya di lantai satu dengan membawa perlengkapan yang dibutuhkan, lalu mengusulkan loket ramah disabilitas di lantai dasar.","Memintanya mengurus lewat calo saja.","Memintanya menunggu sampai ada petugas yang turun.","Meminta rekan membantunya naik ke lantai dua."],"s":[2,5,1,3,4],"w":["Membebani warga.","Inklusif dan memperbaiki fasilitas.","Mengarahkan ke praktik tidak resmi.","Pasif.","Membantu, tetapi berisiko dan kurang nyaman."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: melayani sampai tuntas, ramah, memberi solusi, sesuai prosedur. Waspadai pilihan yang menolak, menyuruh datang lagi tanpa solusi, atau menerima imbalan."}];
